<template>
  <section class="signal-page">
    <div class="signal-toolbar">
      <div class="segmented"><button :class="{active: tab === 'desk'}" @click="tab='desk'">信号台</button><button :class="{active: tab === 'review'}" @click="tab='review'">信号复盘</button></div>
      <label>查看日期 <input v-model="day" type="date" @change="refresh" /></label>
      <button class="secondary" :disabled="store.signalDeskBusy" @click="refresh">刷新</button>
    </div>
    <div v-if="store.signalDeskError" class="service-alert">{{ store.signalDeskError }}</div>
    <div v-if="desk?.health?.status === 'NOT_DEPLOYED'" class="empty-card"><h3>信号服务尚未部署</h3><p>页面已经就绪，但服务器还没有运行实时 15 分钟扫描服务。部署后这里会显示真实信号，不会填充演示数据。</p></div>
    <template v-else-if="desk">
      <div class="signal-answer"><strong>{{ answer }}</strong><span>每个信号都会自动进入模拟账；每日 30 条是工作量保护，不代表被截断的更差。</span></div>
      <div class="signal-kpis">
        <div><span>今日信号</span><strong>{{ desk.summary.signal_count }}</strong><small>{{ desk.summary.undecided_count }} 个待决定</small></div>
        <div><span>我做了 / 放弃</span><strong>{{ desk.summary.taken_count }} / {{ desk.summary.skipped_count }}</strong><small>决定写入不可覆盖账本</small></div>
        <div><span>模拟结果</span><strong :class="rClass(desk.summary.realized_r_total)">{{ r(desk.summary.realized_r_total) }}</strong><small>{{ desk.summary.closed_count }} 笔已结束</small></div>
        <div><span>扫描状态</span><strong>{{ healthLabel }}</strong><small>{{ latestScan }}</small></div>
      </div>

      <template v-if="tab === 'desk'">
        <div class="desk-layout">
          <main class="signal-list">
            <article v-for="signal in desk.signals" :key="signal.signal_id" class="signal-card">
              <header><div><strong>{{ signal.symbol }}</strong><span :class="['direction', signal.direction.toLowerCase()]">{{ signal.direction === 'LONG' ? '做多' : '做空' }}</span><span class="muted">{{ reason(signal) }} · {{ time(signal.signal_time_ms) }}</span></div><span class="scope">{{ scopeLabel(signal.candidate_scope) }}</span></header>
              <SignalCandleChart :symbol="signal.symbol" :before="signal.chart_before || []" :after="signal.simulation?.chart_after || []" :entry="Number(signal.simulation?.entry_price || signal.reference_entry_price)" :stop="Number(signal.simulation?.stop_price || signal.suggested_stop_price)" />
              <div class="signal-levels"><span>参考进场 <b>{{ price(signal.reference_entry_price) }}</b></span><span>止损 <b>{{ price(signal.suggested_stop_price) }}</b></span><span>1R <b>{{ target(signal, 1) }}</b></span><span>2R <b>{{ target(signal, 2) }}</b></span><span>3R <b>{{ target(signal, 3) }}</b></span><span>模拟 <b :class="rClass(signal.simulation?.realized_r)">{{ simulationLabel(signal.simulation) }}</b></span></div>
              <div v-if="signal.decision" class="decision-done">{{ signal.decision.decision === 'TAKEN' ? '已登记：我做了' : `已放弃${signal.decision.reason ? ` · ${signal.decision.reason}` : ''}` }}<button v-if="signal.decision.decision === 'TAKEN' && !signal.manual_execution" class="link-button" @click="openExecution(signal)">登记实际离场</button><span v-if="signal.manual_execution"> · 实际 {{ r(signal.manual_execution.realized_r) }}</span></div>
              <div v-else-if="signal.candidate_scope === 'INCLUDED'" class="decision-actions"><button @click="openTaken(signal)">我做了</button><button class="secondary" @click="openSkipped(signal)">放弃</button></div>
              <div v-else class="decision-done">仅保留模拟记录，不占用人工处理名额</div>
            </article>
            <div v-if="!desk.signals.length" class="empty-card">这一天没有信号。服务正常时，“没有信号”也是有效结果。</div>
          </main>
          <aside class="discipline-card"><h3>今日纪律</h3><dl><div><dt>止损随单</dt><dd>强制</dd></div><div><dt>亏损加仓</dt><dd>禁止</dd></div><div><dt>止损后冷却</dt><dd>同向 4 小时</dd></div><div><dt>计划外交易</dt><dd>不允许登记</dd></div></dl><p v-if="desk.discipline.cooldown_symbols?.length">冷却中：{{ desk.discipline.cooldown_symbols.join('、') }}</p><p class="muted">当前页面只登记与系统信号对应的一次完整交易；不会下单，也不读取账户金额。</p></aside>
        </div>
      </template>

      <template v-else>
        <div class="three-books">
          <div v-for="(book, key) in desk.review" :key="key"><span>{{ bookLabel(key) }}</span><strong :class="rClass(book.realized_r_total)">{{ r(book.realized_r_total) }}</strong><small>{{ book.closed_count }}/{{ book.count }} 笔已有结果 · {{ book.wins }} 盈 {{ book.losses }} 亏</small></div>
        </div>
        <section class="review-section"><h3>我做了的</h3><SignalReviewRow v-for="s in takenSignals" :key="s.signal_id" :signal="s" /></section>
        <section class="review-section"><h3>我没做的</h3><SignalReviewRow v-for="s in skippedSignals" :key="s.signal_id" :signal="s" /></section>
        <div v-if="!takenSignals.length && !skippedSignals.length" class="empty-card">这一天还没有人工决定。先在“信号台”登记做了或放弃，复盘才会形成。</div>
      </template>
    </template>

    <div v-if="dialog" class="signal-modal" @click.self="dialog=null"><form @submit.prevent="submitDialog"><h3>{{ dialog.kind === 'take' ? '登记：我做了' : dialog.kind === 'skip' ? '登记：放弃' : '登记实际离场' }}</h3><p>{{ dialog.signal.symbol }} · {{ dialog.signal.direction === 'LONG' ? '做多' : '做空' }}</p><template v-if="dialog.kind === 'take'"><label>实际进场价<input v-model.number="form.entry_price" type="number" step="any" min="0" required /></label><label>止损价<input v-model.number="form.stop_price" type="number" step="any" min="0" required /></label><small>止损必须位于亏损方向，提交后不可覆盖。</small></template><template v-else-if="dialog.kind === 'skip'"><label>放弃原因<select v-model="form.reason"><option>没盯盘</option><option>不喜欢形态</option><option>市场环境不好</option><option>其他</option></select></label></template><template v-else><label>实际进场价<input v-model.number="form.entry_price" type="number" step="any" min="0" required /></label><label>实际离场价<input v-model.number="form.exit_price" type="number" step="any" min="0" required /></label><label>离场原因<select v-model="form.exit_reason"><option value="MANUAL">主动离场</option><option value="STOP">触发止损</option><option value="TIME_EXIT">时间退出</option></select></label></template><div><button type="button" class="secondary" @click="dialog=null">取消</button><button type="submit">确认并写入账本</button></div></form></div>
  </section>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, onUnmounted, reactive, ref } from "vue";
import SignalCandleChart from "../components/SignalCandleChart.vue";
import { decideSignal, loadSignalDesk, recordSignalExecution, store } from "../stores/appStore.js";
const tab=ref("desk"); const day=ref(new Date().toISOString().slice(0,10)); const dialog=ref(null); const form=reactive({entry_price:0,stop_price:0,exit_price:0,exit_reason:"MANUAL",reason:"没盯盘"}); let timer=null;
const desk=computed(()=>store.signalDesk); const takenSignals=computed(()=>desk.value?.signals?.filter(s=>s.decision?.decision==="TAKEN")||[]); const skippedSignals=computed(()=>desk.value?.signals?.filter(s=>s.decision?.decision==="SKIPPED")||[]);
const answer=computed(()=>!desk.value?.summary?.signal_count?"今天暂时没有信号":`今天 ${desk.value.summary.signal_count} 个信号，${desk.value.summary.undecided_count} 个还没决定`);
const healthLabel=computed(()=>({RUNNING:"运行正常",WAITING_FIRST_SCAN:"等待首次扫描",LEDGER_ERROR:"账本异常"}[desk.value?.health?.status]||desk.value?.health?.status)); const latestScan=computed(()=>desk.value?.health?.latest_scan?`最近扫描 ${time(desk.value.health.latest_scan.signal_close_time_ms)}`:"尚无扫描记录");
function refresh(){return loadSignalDesk(day.value)} function time(ms){return ms?new Date(Number(ms)).toLocaleString("zh-CN",{hour12:false}):"—"} function price(v){return Number(v).toLocaleString("en-US",{maximumSignificantDigits:9})} function r(v){if(v===null||v===undefined)return "待结束";const n=Number(v);return `${n>=0?"+":""}${n.toFixed(2)}R`} function rClass(v){return Number(v)>0?"positive":Number(v)<0?"negative":""}
function target(s,n){const sign=s.direction==="LONG"?1:-1;return price(Number(s.reference_entry_price)+sign*n*Number(s.initial_risk_price))} function reason(s){return s.family_id==="BREAKOUT_MOMENTUM"?`突破 8 小时高点 · 放量 ${Number(s.reason?.relative_quote_volume||0).toFixed(1)} 倍`:`${Number(s.reason?.drop_fraction||0)*100>=0?"下跌":""}${(Number(s.reason?.drop_fraction||0)*100).toFixed(1)}% 后企稳`} function scopeLabel(v){return {INCLUDED:"候选范围内",TRUNCATED:"超过每日 30 条",PENDING_SCOPE:"等待当日排序"}[v]||v} function simulationLabel(s){return s?.status==="CLOSED"?r(s.realized_r):s?.status==="OPEN"?"持有中":"等待进场"} function bookLabel(k){return {all_signal_simulation:"全部信号模拟账",chosen_signal_simulation:"我选择的模拟账",actual_manual:"我的实际成交账"}[k]||k}
function openTaken(s){dialog.value={kind:"take",signal:s};form.entry_price=Number(s.reference_entry_price);form.stop_price=Number(s.suggested_stop_price)} function openSkipped(s){dialog.value={kind:"skip",signal:s};form.reason="没盯盘"} function openExecution(s){dialog.value={kind:"execution",signal:s};form.entry_price=Number(s.decision.entry_price||s.reference_entry_price);form.exit_price=Number(s.simulation?.exit_price||s.reference_entry_price);form.exit_reason="MANUAL"}
async function submitDialog(){const d=dialog.value;if(!d)return;let ok;if(d.kind==="take")ok=await decideSignal({signal_id:d.signal.signal_id,decision:"TAKEN",entry_price:form.entry_price,stop_price:form.stop_price,reason:null});else if(d.kind==="skip")ok=await decideSignal({signal_id:d.signal.signal_id,decision:"SKIPPED",reason:form.reason,entry_price:null,stop_price:null});else ok=await recordSignalExecution({signal_id:d.signal.signal_id,entry_price:form.entry_price,exit_price:form.exit_price,exited_at_ms:Date.now(),exit_reason:form.exit_reason});if(ok)dialog.value=null}
const SignalReviewRow=defineComponent({props:{signal:Object},setup(p){return()=>h("article",{class:"review-row"},[h("div",{class:"review-head"},[h("strong",p.signal.symbol),h("span",p.signal.direction==="LONG"?"做多":"做空"),h("b",{class:rClass(p.signal.manual_execution?.realized_r??p.signal.simulation?.realized_r)},p.signal.decision?.decision==="TAKEN"?(p.signal.manual_execution?`实际 ${r(p.signal.manual_execution.realized_r)}`:"实际成交待登记"):`若机械执行 ${r(p.signal.simulation?.realized_r)}`)]),h(SignalCandleChart,{symbol:p.signal.symbol,before:p.signal.chart_before||[],after:p.signal.simulation?.chart_after||[],entry:Number(p.signal.simulation?.entry_price||p.signal.reference_entry_price),stop:Number(p.signal.simulation?.stop_price||p.signal.suggested_stop_price)}),h("p",{class:"muted"},p.signal.decision?.decision==="TAKEN"?`机械结果 ${r(p.signal.simulation?.realized_r)}；实际结果 ${r(p.signal.manual_execution?.realized_r)}`:`放弃原因：${p.signal.decision?.reason||"未填写"}`)])}});
onMounted(()=>{refresh();timer=setInterval(refresh,15000)});onUnmounted(()=>clearInterval(timer));
</script>

<style scoped>
.signal-page{display:grid;gap:14px}.signal-toolbar,.signal-answer,.signal-card,.discipline-card,.review-section,.empty-card{background:#101a2c;border:1px solid #203655;border-radius:10px;padding:14px}.signal-toolbar{display:flex;align-items:center;gap:12px}.signal-toolbar label{margin-left:auto;color:#91a2bb}.signal-toolbar input,.signal-modal input,.signal-modal select{background:#0a1424;border:1px solid #2a4264;color:#e9f0fa;border-radius:6px;padding:8px}.segmented{display:flex}.segmented button{border-radius:0}.segmented button:first-child{border-radius:6px 0 0 6px}.segmented button:last-child{border-radius:0 6px 6px 0}.segmented button:not(.active),button.secondary{background:#0d1728;color:#9bacc3;border:1px solid #29405f}.signal-answer{display:flex;justify-content:space-between;gap:20px}.signal-answer span,.muted{color:#8293aa}.signal-kpis,.three-books{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.signal-kpis>div,.three-books>div{background:#101a2c;border:1px solid #203655;border-radius:10px;padding:14px;display:grid;gap:5px}.signal-kpis span,.three-books span{color:#8293aa}.signal-kpis strong,.three-books strong{font-size:22px}.signal-kpis small,.three-books small{color:#687b97}.desk-layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:14px;align-items:start}.signal-list{display:grid;gap:12px}.signal-card header,.review-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:10px}.direction,.scope{display:inline-block;margin-left:8px;padding:3px 7px;border-radius:999px;font-size:12px}.direction.long{color:#78d9b6;background:#123c37}.direction.short{color:#ff8c98;background:#43242c}.scope{color:#81baff;background:#172e50}.signal-levels{display:flex;flex-wrap:wrap;gap:8px 20px;margin:10px 0;color:#8293aa}.signal-levels b{color:#dbe7f8}.decision-actions,.decision-done{display:flex;align-items:center;gap:10px}.decision-done{border-top:1px solid #203655;padding-top:10px;color:#8cb9ed}.link-button{background:none;border:0;color:#66aaff;text-decoration:underline}.discipline-card{position:sticky;top:90px}.discipline-card dl>div{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #203655}.discipline-card dd{color:#69d4ad}.three-books{grid-template-columns:repeat(3,minmax(0,1fr))}.review-section{display:grid;gap:12px}.review-row{background:#0b1525;border:1px solid #1d304c;border-radius:8px;padding:12px}.positive{color:#64d3aa!important}.negative{color:#ef6a79!important}.signal-modal{position:fixed;inset:0;background:#020815c9;display:grid;place-items:center;z-index:50}.signal-modal form{width:min(420px,calc(100vw - 30px));background:#111d31;border:1px solid #315078;border-radius:10px;padding:20px;display:grid;gap:12px}.signal-modal label{display:grid;gap:6px}.signal-modal form>div{display:flex;justify-content:flex-end;gap:10px}@media(max-width:900px){.desk-layout{grid-template-columns:1fr}.discipline-card{position:static}.signal-kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.signal-toolbar,.signal-answer{align-items:stretch;flex-direction:column}.signal-toolbar label{margin-left:0}.signal-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.three-books{grid-template-columns:1fr}.signal-kpis>div{padding:11px}.signal-kpis strong{font-size:19px}.signal-card{padding:10px}.signal-card header,.review-head{align-items:flex-start;flex-direction:column}}
</style>
